import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageTeachers() {
  const [teachers, setTeachers] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState(null);
  const [formData, setFormData] = useState({ name: '', username: '', subject: 'Mathematics', qualifications: '', email: '', phone_number: '', address: '', password: 'TC@123' });
  const [searchQuery, setSearchQuery] = useState('');

  const availableSubjects = ['Mathematics', 'Science', 'English', 'Sinhala', 'ICT', 'Accounting', 'Business Studies', 'Dancing', 'History'];

  const fetchTeachers = () => axios.get('http://localhost:8081/api/view-teachers').then(res => setTeachers(res.data));
  
  useEffect(() => { 
      fetchTeachers(); 
  }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    const apiPath = isEditing ? `http://localhost:8081/api/edit-teacher/${editId}` : 'http://localhost:8081/api/add-teacher';
    const method = isEditing ? axios.put : axios.post;

    method(apiPath, formData).then((res) => { 
        if(res.data.status === "Error") {
            alert("Database Error: " + res.data.error); 
        } else {
            fetchTeachers(); 
            resetForm(); 
            alert("Success!"); 
        }
    }).catch(err => alert("Server connection error!"));
  };

  const handleEdit = (t) => {
    setIsEditing(true); 
    setEditId(t.id);
    setFormData({ 
      name: t.name, 
      username: t.username || '', 
      subject: t.Subject || t.subject || 'Mathematics', 
      qualifications: t.qualifications || '', 
      email: t.email || '', 
      phone_number: t.phone_number, 
      address: t.address || '', 
      password: 'TC@123'
    });
    setShowForm(true);
  };

  const resetForm = () => { 
      setShowForm(false); 
      setIsEditing(false); 
      setEditId(null); 
      setFormData({ name: '', username: '', subject: 'Mathematics', qualifications: '', email: '', phone_number: '', address: '', password: 'TC@123' }); 
  };
  
  const filteredTeachers = [...teachers].sort((a, b) => b.id - a.id).filter(t => t.name.toLowerCase().includes(searchQuery.toLowerCase()));

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif', animation: 'fadeIn 0.5s', backgroundColor: '#f8fafc', minHeight: '100vh' }}>
      
      {/* Header Section */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px', backgroundColor: '#fff', padding: '15px 25px', borderRadius: '12px', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)' }}>
        <h2 style={{ margin: 0, color: '#1e293b', fontSize: '24px', display: 'flex', alignItems: 'center', gap: '10px' }}>
          🧑‍🏫 Manage Teachers
        </h2>
        <button onClick={() => { resetForm(); setShowForm(true); }} style={{ padding: '10px 20px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px', transition: 'background 0.3s' }}>
          + Add Teacher
        </button>
      </div>

      {/* Table Section */}
      <div style={{ backgroundColor: '#fff', borderRadius: '12px', overflowX: 'auto', boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)', padding: '10px' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left', minWidth: '1000px' }}>
          <thead>
            <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
              <th style={thStyle}>Name</th>
              <th style={thStyle}>Subject</th>
              <th style={thStyle}>Qualifications</th>
              <th style={thStyle}>Telephone</th>
              <th style={thStyle}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredTeachers.map(t => (
              <tr key={t.id} style={{ borderBottom: '1px solid #f1f5f9', transition: 'background 0.2s' }} onMouseOver={(e) => e.currentTarget.style.backgroundColor = '#f8fafc'} onMouseOut={(e) => e.currentTarget.style.backgroundColor = 'transparent'}>
                <td style={{...tdStyle, color: '#15803d', fontWeight: 'bold'}}>{t.name}</td>
                <td style={{...tdStyle, fontWeight: 'bold', color: '#334155'}}>{t.Subject || t.subject || '-'}</td>
                <td style={{...tdStyle, maxWidth: '220px', color: '#475569'}}>{t.qualifications || '-'}</td>
                <td style={{...tdStyle, whiteSpace: 'nowrap', color: '#475569'}}>{t.phone_number}</td>
                <td style={tdStyle}>
                  <button onClick={() => handleEdit(t)} style={{ cursor: 'pointer', padding: '6px 12px', backgroundColor: '#fff', border: '1px solid #cbd5e1', borderRadius: '6px', fontSize: '14px', transition: 'all 0.2s' }}>✏️ Edit</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Popup Form */}
      {showForm && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000, backdropFilter: 'blur(4px)' }}>
          <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', width: '500px', boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1)' }}>
            <h3 style={{ marginTop: 0, marginBottom: '20px', color: '#1e293b', borderBottom: '2px solid #f1f5f9', paddingBottom: '10px' }}>
              {isEditing ? '✏️ Edit Teacher' : '➕ Add New Teacher'}
            </h3>
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              <div>
                <label style={labelStyle}>Full Name</label>
                <input type="text" placeholder="Enter full name" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} required style={inputStyle} />
              </div>
              <div>
                <label style={labelStyle}>Subject</label>
                <select value={formData.subject} onChange={e => setFormData({...formData, subject: e.target.value})} style={inputStyle} required>
                  {availableSubjects.map(sub => <option key={sub} value={sub}>{sub}</option>)}
                </select>
              </div>
              <div>
                <label style={labelStyle}>Phone Number</label>
                <input type="text" placeholder="07x xxxxxxx" value={formData.phone_number} onChange={e => setFormData({...formData, phone_number: e.target.value})} required style={inputStyle} />
              </div>
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '10px', marginTop: '10px' }}>
                <button type="button" onClick={resetForm} style={{ padding: '10px 20px', backgroundColor: '#f1f5f9', color: '#475569', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>Cancel</button>
                <button type="submit" style={{ padding: '10px 20px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>{isEditing ? 'Update' : 'Save'}</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

const labelStyle = { display: 'block', marginBottom: '5px', fontSize: '14px', fontWeight: 'bold', color: '#475569' };
const inputStyle = { padding: '12px', borderRadius: '8px', border: '1px solid #cbd5e1', width: '100%', boxSizing: 'border-box', outline: 'none' };
const thStyle = { padding: '15px 20px', textAlign: 'left', color: '#475569', fontWeight: 'bold', fontSize: '15px' };
const tdStyle = { padding: '15px 20px', fontSize: '14px' };
